<template><div class="page"><div class="head"><div><span>REFLIGHT & RELEASE</span><h2>再飞可行性与发射放行评估</h2><p>调用项目组训练的 VAE-GAN 与随机森林模型，结合子系统健康、寿命裕度和告警生成整器级辅助结论。</p></div><el-tag type="warning">最终结论须人工签署</el-tag></div><div class="grid"><el-card shadow="never"><template #header><b>评估输入</b></template><el-form label-width="120px"><el-form-item label="运载器编号"><el-input v-model="form.vehicle_id"/></el-form-item><el-form-item label="任务名称"><el-input v-model="form.mission_name"/></el-form-item><el-form-item v-for="item in subsystems" :key="item.key" :label="item.key+' HI'"><el-slider v-model="item.percent" :min="0" :max="100" show-input/></el-form-item><el-form-item label="寿命裕度"><el-slider v-model="rulPercent" :min="0" :max="100" show-input/></el-form-item><el-form-item label="严重告警"><el-input-number v-model="form.open_critical_alarms" :min="0" :max="20"/></el-form-item><el-form-item label="放行阈值"><el-input-number v-model="form.release_threshold" :min=".5" :max=".99" :step=".01"/></el-form-item><el-button type="primary" :loading="loading" @click="run">执行放行评估</el-button></el-form></el-card><el-card shadow="never"><template #header><b>评估结论</b></template><el-empty v-if="!result" description="等待执行评估"/><template v-else><div :class="['decision',result.decision]"><small>辅助决策</small><strong>{{result.decision_label}}</strong><span>任务成功概率 {{pct(result.mission_success_probability)}}</span></div><el-progress type="dashboard" :percentage="Math.round(result.mission_success_probability*100)" :status="result.decision==='release'?'success':'exception'"/><el-descriptions border :column="2"><el-descriptions-item label="系统健康指数">{{result.system_health_index}}</el-descriptions-item><el-descriptions-item label="RBD等效健康">{{result.rbd_equivalent_health}}</el-descriptions-item><el-descriptions-item label="VAE重构误差">{{modelResult?.reconstruction_error?.toFixed(6)??'—'}}</el-descriptions-item><el-descriptions-item label="GAN置信度">{{modelResult?pct(modelResult.gan_confidence):'—'}}</el-descriptions-item><el-descriptions-item label="RF健康概率">{{modelResult?pct(modelResult.rf_probability):'—'}}</el-descriptions-item><el-descriptions-item label="模型状态">{{modelStatus}}</el-descriptions-item></el-descriptions><el-alert v-if="result.blockers.length" title="放行阻断项" type="error" :closable="false"><template #default><ul><li v-for="x in result.blockers" :key="x">{{x}}</li></ul></template></el-alert><el-alert v-else title="所有判据均已通过" type="success" :closable="false"/><p class="note">若运行环境缺少 PyTorch，后端会记录回退原因，不会把基线计算冒充为训练模型结果。</p></template></el-card></div><el-card shadow="never" class="history"><template #header><b>最近评估记录</b></template><el-table :data="history"><el-table-column prop="created_at" label="时间"><template #default="s">{{new Date(s.row.created_at).toLocaleString()}}</template></el-table-column><el-table-column prop="vehicle_id" label="运载器"/><el-table-column prop="mission_name" label="任务"/><el-table-column prop="mission_success_probability" label="成功概率"><template #default="s">{{pct(s.row.mission_success_probability)}}</template></el-table-column><el-table-column prop="decision_label" label="结论"><template #default="s"><el-tag :type="s.row.decision==='release'?'success':'danger'">{{s.row.decision_label}}</el-tag></template></el-table-column></el-table></el-card></div></template>
<script setup>import{ref,computed,onMounted}from'vue';import{ElMessage}from'element-plus';const form=ref({vehicle_id:'RLV-DEMO-01',mission_name:'重复使用运载器发射任务',open_critical_alarms:0,release_threshold:.85}),subsystems=ref([{key:'动力',percent:93},{key:'电源',percent:91},{key:'测控',percent:90},{key:'导航制导与控制',percent:92},{key:'结构',percent:95}]),rulPercent=ref(90),loading=ref(false),result=ref(),history=ref([]);const pct=v=>`${(Number(v)*100).toFixed(1)}%`,modelResult=computed(()=>result.value?.algorithm_trace?.model_result),modelStatus=computed(()=>{const s=result.value?.algorithm_trace?.vae_gan_status;if(s==='evidence_only_uncalibrated')return'RF已校准量纲；VAE-GAN仅作证据';if(s==='inference_completed')return'训练模型推理完成';return`已回退：${result.value?.algorithm_trace?.model_error||'运行环境不可用'}`});async function load(){const j=await(await fetch('/api/v1/phm/release-assessments/')).json();history.value=j.results||[]}async function run(){loading.value=true;try{const payload={...form.value,rul_margin:rulPercent.value/100,subsystem_health:Object.fromEntries(subsystems.value.map(x=>[x.key,x.percent/100]))};const r=await fetch('/api/v1/phm/release-assessments/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const j=await r.json();if(!r.ok)throw Error(j.error);result.value=j.assessment;await load();ElMessage.success('放行评估已完成并留痕')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}onMounted(load)</script>
<style scoped>.page{max-width:1280px}.head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.head span{font-size:12px;color:#1677ff;letter-spacing:1px}.head h2{margin:8px 0}.head p,.note{color:#718198}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.decision{padding:20px;border-radius:10px;margin-bottom:18px}.decision small,.decision strong,.decision span{display:block}.decision strong{font-size:30px;margin:8px 0}.decision.release{background:#ebf8f2;color:#16835b}.decision.hold{background:#fff0f0;color:#c43c3c}.el-progress{display:flex;justify-content:center;margin:16px}.el-alert{margin-top:16px}.history{margin-top:18px}@media(max-width:900px){.grid{grid-template-columns:1fr}}</style>
